DPK_Id = 12 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''N23'', CASE WHEN d.DPK_Id = 13 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''V23'', CASE WHEN d.DPK_Id = 14 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''N8'', CASE WHEN d.DPK_Id = 15 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''V8'', CASE WHEN d.DPK_Id = 16 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''N5'', CASE WHEN d.DPK_Id = 17 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''V5'', CASE WHEN d.DPK_Id = 18 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''NNPoo'', CASE WHEN d.DPK_Id = 19 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''VNPoo'', CASE WHEN d.DPK_Id = 20 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''NNP'', CASE WHEN d.DPK_Id = 21 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''VNP'', CASE WHEN d.DPK_Id = 22 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''N0'', CASE WHEN d.DPK_Id = 23 THEN Case When l.PEL_WartoscString <>'''' Then Convert(Decimal(18,2),l.PEL_WartoscString) end ELSE NULL END ''Nzw'' from CDN.PodElemListy l join cdn.PodNag n on l.PEL_PONNumer=n.PON_GIDNumer join cdn.DefPodElem e on l.PEL_POELp = e.DPE_Id join CDN.DefPodElemKolumny d on e.DPE_DPNID=d.DPK_DPNId and e.DPE_Lp = d.DPK_DPELp and l.PEL_DPKId = d.DPK_Id WHERE DPE_DPNId = @PONDPNId and l.PEL_PONNumer = @PONGIDNumer and l.PEL_POELp=27 and l.PE